<?php
function flowLeagueStanding(PDO $db,int $league,int $uid,DateTimeImmutable $start,DateTimeImmutable $end):array {
 $q=$db->prepare('SELECT u.id,COALESCE(SUM(CASE WHEN f.id IS NOT NULL THEN p.points ELSE 0 END),0) pts FROM league_members m JOIN users u ON u.id=m.user_id LEFT JOIN predictions p ON p.user_id=u.id LEFT JOIN fixtures f ON f.id=p.fixture_id AND julianday(f.kickoff_utc)>=julianday(?) AND julianday(f.kickoff_utc)<julianday(?) WHERE m.league_id=? GROUP BY u.id');
 $q->execute([$start->format('c'),$end->format('c'),$league]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);$pts=0;foreach($rows as $r)if((int)$r['id']===$uid)$pts=(int)$r['pts'];return ['rank'=>1+count(array_filter($rows,fn($r)=>(int)$r['pts']>$pts)),'pts'=>$pts];
}
function renderOverallLeagues(bool $listed,int $uid):void { ?>
<section class="flowoverall"><h3>Overall competitions</h3><p>One set of predictions earns points in the season competition, each monthly competition and all your friend leagues. No extra predictions needed.</p><div class="flowleaguegrid"><a class="flowleague" href="/leagues?global=1"><strong>Season competition</strong><span>Everyone + computer players · all season</span><b>View season table →</b></a><a class="flowleague" href="/leagues?global=1&amp;table=<?=date('Y-m')?>"><strong>Monthly competition</strong><span>A fresh points race each month</span><b>View this month →</b></a></div><p class="flowmuted"><?=$uid<1?'Save your first prediction to start competing.':($listed?'You’re included automatically in the overall competitions.':'Your points count now. Your overall-table row is visible only to you until you predict in two matchweeks or add an email.')?></p></section>
<?php }
function renderPlayerHome(PDO $db,int $uid,array $user,array $week,array $leagues,DateTimeImmutable $start,DateTimeImmutable $end,array $pred):void {
 if(!empty($_GET['screen']))return;
 ?>
<section class="flowhome" aria-label="Your next steps">
<?php if($uid>0):?><div class="flowwelcome"><div><p class="floweyebrow">YOUR MATCHDAY</p><h1>Welcome back, <?=htmlspecialchars((string)$user['display_name'])?>.</h1><p>Make your predictions, follow your leagues and see how you’re doing.</p></div><a class="ghost" href="/my-results">My results →</a></div><div class="flowstats"><a class="flowstat" href="#predict"><strong id="homePickProgress"><?=$week['saved']?> / <?=$week['total']?></strong><span>Predictions saved for <?=htmlspecialchars($week['label'])?></span></a><a class="flowstat" href="/leagues"><strong><?=count($leagues)?></strong><span>Friend <?=count($leagues)===1?'league':'leagues'?> · plus the overall competitions</span></a><a class="flowstat" href="/leagues?global=1&amp;table=season"><?php $q=$db->prepare('SELECT COALESCE(SUM(p.points),0) FROM predictions p JOIN fixtures f ON f.id=p.fixture_id WHERE p.user_id=? AND julianday(f.kickoff_utc)>=julianday(?) AND julianday(f.kickoff_utc)<julianday(?)');$q->execute([$uid,$start->format('c'),$end->format('c')]);?><strong><?=(int)$q->fetchColumn()?> pts</strong><span>Your season points</span></a></div><div class="flownext"><a class="btn" href="/#predict" onclick="document.getElementById('predict').scrollIntoView({block:'start'});finishMissingPicks();return false" id="homeFinishPicks"><?=$week['missing']?'Finish my predictions':'Review my predictions'?></a><span id="homeDeadline"><?=$week['deadline']?'Next deadline: '.(new DateTimeImmutable($week['deadline'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Europe/London'))->format('D j M, H:i').' UK':'No upcoming deadline — check back for the next fixtures.'?></span></div><h2>My leagues <a href="/leagues">See all →</a></h2><div class="flowleaguegrid"><a class="flowleague" href="/leagues?global=1"><strong>Overall competition</strong><span>Season and monthly tables · friends and bots</span><b>See how you’re doing →</b></a><?php foreach(array_slice($leagues,0,3) as $l):$standing=flowLeagueStanding($db,(int)$l['id'],$uid,$start,$end);?><article class="flowleague"><strong><?=htmlspecialchars($l['name'])?></strong><span>Season #<?=$standing['rank']?> · <?=$standing['pts']?> pts · <?=(int)$l['member_count']?> members</span><div><a href="/leagues?league=<?=(int)$l['id']?>">View league →</a><button class="textbtn" type="button" data-name="<?=htmlspecialchars($l['name'],ENT_QUOTES)?>" data-code="<?=htmlspecialchars($l['code'],ENT_QUOTES)?>" onclick="shareLeague(this.dataset.name,this.dataset.code)">Invite friends</button></div></article><?php endforeach;?></div><?php if(!$leagues):?><p class="flowmuted">Make it a friendly rivalry. <a href="/leagues#lname">Create a league</a> and invite your friends, or <a href="/leagues#lcode">join with an invite code</a>.</p><?php endif;?>
<?php else:?><ol class="flowsteps"><li><b>1. Choose a score</b><span>Pick the home and away goals. 0–0 counts too.</span></li><li><b>2. Save before kick-off</b><span>Choose your player name when you save your first prediction.</span></li><li><b>3. Follow the competition</b><span>Earn points, challenge friends and beat computer players.</span></li></ol><?php endif;?>
</section>
